def generate_pristine_database(target_count=2150):
    recipes = []
    current_id = 1
    generated_titles = set()

    # Function to add a recipe safely avoiding title collision
    def add_recipe(title, cuisine, category, ingredients, diet_tags, prep_t, cook_t, tip, instructions=None):
        nonlocal current_id
        if title in generated_titles:
            return False
        generated_titles.add(title)

        # Build deeply tailored, authentic culinary instructions based on recipe ingredients and archetype
        if not instructions:
            items = [ing["item"] if isinstance(ing, dict) else ing for ing in ingredients]
            items_str = " ".join(items)
            t = title.lower()

            meat = "اللحم الضأن أو العجل البلدي"
            if "دجاج" in items_str or "فروج" in items_str:
                meat = "الدجاج الطازج"
            elif "سمك" in items_str or "روبيان" in items_str or "بحري" in items_str:
                meat = "السمك وثمار البحر"

            clean_ghee = "السمنة البلدية الحيوانية"
            clean_oil = "زيت الزيتون البكر الممتاز"
            clean_rice = "الأرز قصير الحبة المغسول والمصفى"
            clean_yogurt = "لبن الزبادي كامل الدسم"
            clean_pom = "دبس الرمان الطبيعي الحامض"
            clean_tahini = "طحينة السمسم الفاخرة"
            clean_nuts = "الفستق الحلبي الأخضر المجروش" if ("فستق" in items_str or category == "حلويات ومشروبات") else "الصنوبر واللوز المحمص بالسمن البلدي"

            # 1. DESSERTS, SWEETS & DRINKS (حلويات ومشروبات)
